{
  "apiVersion": "dashboard.grafana.app/v1beta1",
  "kind": "Dashboard",
  "metadata": { "name": "day25-work-view-v6", "annotations": { "grafana.app/folder": "day25" } },
  "spec": {
    "uid": "day25-work-view-v6",
    "title": "取消的訂單都處理完了嗎？",
    "tags": ["day25", "notification"],
    "timezone": "browser",
    "schemaVersion": 36,
    "refresh": "",
    "time": { "from": "now-5m", "to": "now" },
    "templating": { "list": [] },
    "panels": [
      {
        "id": 1, "type": "stat", "title": "狀態",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 5, "w": 6, "x": 0, "y": 0 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "min((max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range]))*0+1) or (max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"unknown\"}[$__range]))*0+2) or (max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"matched\"}[$__range]))*0+3))" }
        ],
        "fieldConfig": {
          "defaults": { "noValue": "? 無資料", "color": { "mode": "thresholds" },
            "mappings": [ { "type": "value", "options": {
              "1": { "text": "✗ 沒處理完", "color": "red", "index": 0 },
              "2": { "text": "? 紀錄不全", "color": "#808080", "index": 1 },
              "3": { "text": "✓ 都處理完了", "color": "green", "index": 2 } } } ] },
          "overrides": []
        },
        "options": { "reduceOptions": { "values": false, "calcs": ["lastNotNull"], "fields": "/^Value$/" },
          "colorMode": "background", "graphMode": "none", "textMode": "value", "justifyMode": "center", "orientation": "auto", "wideLayout": true,
          "text": { "titleSize": 18 } }
      },
      {
        "id": 2, "type": "stat", "title": "取消成功",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 5, "w": 6, "x": 6, "y": 0 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "(sum(abs(max by (run)(last_over_time(flow_count{job=\"day25-work-view\",stage_order=\"2\"}[$__range])) - on(run) max by (run)(last_over_time(request_outcome{job=\"day25-work-view\",outcome=\"取消成功\"}[$__range])))) + sum(last_over_time(request_outcome{job=\"day25-work-view\",outcome=\"系統錯誤\"}[$__range]))) or vector(0)" }
        ],
        "fieldConfig": {
          "defaults": { "color": { "mode": "thresholds" },
            "mappings": [
              { "type": "value", "options": { "0": { "text": "✓ 全部", "color": "green", "index": 0 } } },
              { "type": "range", "options": { "from": 0.0001, "to": 1000000000, "result": { "text": "✗ 有缺", "color": "red", "index": 1 } } } ] },
          "overrides": []
        },
        "options": { "reduceOptions": { "values": false, "calcs": ["lastNotNull"], "fields": "/^Value$/" },
          "colorMode": "background", "graphMode": "none", "textMode": "value", "justifyMode": "center", "orientation": "auto", "wideLayout": true,
          "text": { "titleSize": 18 } }
      },
      {
        "id": 3, "type": "stat", "title": "客人被告知",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 5, "w": 6, "x": 12, "y": 0 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "100 * sum(last_over_time(work_matched{job=\"day25-work-view\"}[$__range]) and on(run) (max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range])) or (max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"matched\"}[$__range])) unless on() max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range]))))) / sum(last_over_time(work_expected{job=\"day25-work-view\"}[$__range]) and on(run) (max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range])) or (max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"matched\"}[$__range])) unless on() max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range]))))) " }
        ],
        "fieldConfig": {
          "defaults": { "unit": "percent", "decimals": 0, "noValue": "? 無資料", "color": { "mode": "thresholds" },
            "thresholds": { "mode": "absolute", "steps": [ { "color": "red", "value": null }, { "color": "green", "value": 100 } ] },
            "mappings": [] },
          "overrides": []
        },
        "options": { "reduceOptions": { "values": false, "calcs": ["lastNotNull"], "fields": "/^Value$/" },
          "colorMode": "background", "graphMode": "none", "textMode": "value", "justifyMode": "center", "orientation": "auto", "wideLayout": true,
          "text": { "titleSize": 18 } }
      },
      {
        "id": 4, "type": "stat", "title": "退款",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 5, "w": 6, "x": 18, "y": 0 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "(max(last_over_time(flow_stage_info{job=\"day25-work-view\",stage_order=\"8\",available=\"無資料\"}[$__range]))*0+3) or (max(last_over_time(flow_stage_info{job=\"day25-work-view\",stage_order=\"8\",available=\"有\"}[$__range]))*0+1)" }
        ],
        "fieldConfig": {
          "defaults": { "noValue": "? 無資料", "color": { "mode": "thresholds" },
            "mappings": [ { "type": "value", "options": {
              "3": { "text": "? 無資料", "color": "#808080", "index": 0 },
              "1": { "text": "有資料", "color": "green", "index": 1 } } } ] },
          "overrides": []
        },
        "options": { "reduceOptions": { "values": false, "calcs": ["lastNotNull"], "fields": "/^Value$/" },
          "colorMode": "background", "graphMode": "none", "textMode": "value", "justifyMode": "center", "orientation": "auto", "wideLayout": true,
          "text": { "titleSize": 18 } }
      },
      {
        "id": 11, "type": "stat", "title": "",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 2, "w": 6, "x": 0, "y": 5 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "label_replace(label_join(((max by (run, scenario, stage, stage_order)(last_over_time(flow_count{job=\"day25-work-view\",stage_order=\"4\"}[$__range])) < on(run) group_left() max by (run)(last_over_time(flow_count{job=\"day25-work-view\",stage_order=\"2\"}[$__range]))) or (max by (run, scenario, stage, stage_order)(last_over_time(flow_count{job=\"day25-work-view\",stage_order=\"5\"}[$__range])) < on(run) group_left() max by (run)(last_over_time(flow_count{job=\"day25-work-view\",stage_order=\"4\"}[$__range]))) or (max by (run, scenario, stage, stage_order)(last_over_time(flow_count{job=\"day25-work-view\",stage_order=\"6\"}[$__range])) < on(run) group_left() max by (run)(last_over_time(flow_count{job=\"day25-work-view\",stage_order=\"5\"}[$__range])))) and on(run) max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range])), \"sub\", \"|\", \"stage\", \"scenario\"), \"sub\", \"卡在「$1」：$2\", \"sub\", \"(.*)[|](.*)\")" }
        ],
        "fieldConfig": { "defaults": { "noValue": "沒有卡住的項目", "color": { "mode": "fixed", "fixedColor": "text" } }, "overrides": [] },
        "options": { "reduceOptions": { "values": false, "calcs": ["lastNotNull"], "fields": "/^sub$/" },
          "colorMode": "none", "graphMode": "none", "textMode": "value", "justifyMode": "center", "orientation": "auto", "wideLayout": true,
          "text": { "valueSize": 16 } }
      },
      {
        "id": 12, "type": "stat", "title": "",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 2, "w": 6, "x": 6, "y": 5 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "label_replace(vector(1), \"sub\", \"被拒、重複取消另計（業務規則）\", \"\", \"\")" }
        ],
        "fieldConfig": { "defaults": { "color": { "mode": "fixed", "fixedColor": "text" } }, "overrides": [] },
        "options": { "reduceOptions": { "values": false, "calcs": ["lastNotNull"], "fields": "/^sub$/" },
          "colorMode": "none", "graphMode": "none", "textMode": "value", "justifyMode": "center", "orientation": "auto", "wideLayout": true,
          "text": { "valueSize": 16 } }
      },
      {
        "id": 13, "type": "stat", "title": "",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 2, "w": 6, "x": 12, "y": 5 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "label_replace(label_join(count_values(\"m\", sum(last_over_time(work_matched{job=\"day25-work-view\"}[$__range]) and on(run) (max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range])) or (max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"matched\"}[$__range])) unless on() max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range]))))))  * on() group_left(e) count_values(\"e\", sum(last_over_time(work_expected{job=\"day25-work-view\"}[$__range]) and on(run) (max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range])) or (max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"matched\"}[$__range])) unless on() max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range])))))), \"sub\", \"／\", \"m\", \"e\"), \"sub\", \"對方收到 $1\", \"sub\", \"(.*)\")" }
        ],
        "fieldConfig": { "defaults": { "noValue": "沒有資料", "color": { "mode": "fixed", "fixedColor": "text" } }, "overrides": [] },
        "options": { "reduceOptions": { "values": false, "calcs": ["lastNotNull"], "fields": "/^sub$/" },
          "colorMode": "none", "graphMode": "none", "textMode": "value", "justifyMode": "center", "orientation": "auto", "wideLayout": true,
          "text": { "valueSize": 16 } }
      },
      {
        "id": 14, "type": "stat", "title": "",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 2, "w": 6, "x": 18, "y": 5 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "label_replace(max by (note)(last_over_time(flow_stage_info{job=\"day25-work-view\",stage_order=\"8\"}[$__range])) * 0 + 1, \"sub\", \"$1\", \"note\", \"(.*)\")" }
        ],
        "fieldConfig": { "defaults": { "noValue": "沒有", "color": { "mode": "fixed", "fixedColor": "text" } }, "overrides": [] },
        "options": { "reduceOptions": { "values": false, "calcs": ["lastNotNull"], "fields": "/^sub$/" },
          "colorMode": "none", "graphMode": "none", "textMode": "value", "justifyMode": "center", "orientation": "auto", "wideLayout": true,
          "text": { "valueSize": 16 } }
      },
      { "id": 20, "type": "row", "title": "卡在哪？", "collapsed": false, "gridPos": { "h": 1, "w": 24, "x": 0, "y": 7 }, "panels": [] },
      {
        "id": 21, "type": "stat", "title": "",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 4, "w": 24, "x": 0, "y": 8 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "((((max by (run, stage, stage_order)(last_over_time(flow_count{job=\"day25-work-view\",stage_order=\"4\"}[$__range])) < on(run) group_left() max by (run)(last_over_time(flow_count{job=\"day25-work-view\",stage_order=\"2\"}[$__range]))) or (max by (run, stage, stage_order)(last_over_time(flow_count{job=\"day25-work-view\",stage_order=\"5\"}[$__range])) < on(run) group_left() max by (run)(last_over_time(flow_count{job=\"day25-work-view\",stage_order=\"4\"}[$__range]))) or (max by (run, stage, stage_order)(last_over_time(flow_count{job=\"day25-work-view\",stage_order=\"6\"}[$__range])) < on(run) group_left() max by (run)(last_over_time(flow_count{job=\"day25-work-view\",stage_order=\"5\"}[$__range])))) * 0 + 2) or (max by (run, stage, stage_order)(last_over_time(flow_stage_info{job=\"day25-work-view\",available=\"無資料\"}[$__range])) * 0 + 3) or (max by (run, stage, stage_order)(last_over_time(flow_count{job=\"day25-work-view\"}[$__range])) * 0 + 1)) and on(run) max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range]))" }
        ],
        "transformations": [
          { "id": "sortBy", "options": { "fields": {}, "sort": [ { "field": "stage_order" } ] } },
          { "id": "organize", "options": { "excludeByName": { "Time": true, "run": true, "stage_order": true } } }
        ],
        "fieldConfig": {
          "defaults": { "noValue": "沒有卡住的項目", "color": { "mode": "thresholds" },
            "mappings": [ { "type": "value", "options": {
              "1": { "text": "✓ 正常", "color": "green", "index": 0 },
              "2": { "text": "✗ 卡住", "color": "red", "index": 1 },
              "3": { "text": "? 無資料", "color": "#808080", "index": 2 } } } ] },
          "overrides": []
        },
        "options": { "reduceOptions": { "values": true, "calcs": [], "fields": "/^Value$/" },
          "colorMode": "background", "graphMode": "none", "textMode": "value_and_name", "justifyMode": "center", "orientation": "vertical", "wideLayout": true,
          "text": { "titleSize": 16 } }
      },
      {
        "id": 22, "type": "stat", "title": "",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 3, "w": 24, "x": 0, "y": 12 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "((max by (run, stage, stage_order)(last_over_time(flow_count{job=\"day25-work-view\"}[$__range]))) or (max by (run, stage, stage_order)(last_over_time(flow_stage_info{job=\"day25-work-view\",available=\"無資料\"}[$__range])) * 0 - 1)) and on(run) max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range]))" }
        ],
        "transformations": [
          { "id": "sortBy", "options": { "fields": {}, "sort": [ { "field": "stage_order" } ] } },
          { "id": "organize", "options": { "excludeByName": { "Time": true, "run": true, "stage_order": true } } }
        ],
        "fieldConfig": {
          "defaults": { "noValue": "沒有", "unit": "suffix: 筆", "decimals": 0, "color": { "mode": "fixed", "fixedColor": "text" },
            "mappings": [ { "type": "value", "options": { "-1": { "text": "—", "color": "#808080", "index": 0 } } } ] },
          "overrides": []
        },
        "options": { "reduceOptions": { "values": true, "calcs": [], "fields": "/^Value$/" },
          "colorMode": "none", "graphMode": "none", "textMode": "value_and_name", "justifyMode": "center", "orientation": "vertical", "wideLayout": true,
          "text": { "titleSize": 16 } }
      },
      {
        "id": 23, "type": "table", "title": "無資料的段落",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 4, "w": 24, "x": 0, "y": 15 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "(max by (run, stage, stage_order, note)(last_over_time(flow_stage_info{job=\"day25-work-view\",available=\"無資料\"}[$__range]))) and on(run) max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range]))" }
        ],
        "transformations": [
          { "id": "sortBy", "options": { "fields": {}, "sort": [ { "field": "stage_order" } ] } },
          { "id": "organize", "options": {
            "excludeByName": { "Time": true, "run": true, "stage_order": true, "Value": true },
            "indexByName": { "stage": 0, "note": 1 },
            "renameByName": { "stage": "段落", "note": "說明" } } }
        ],
        "fieldConfig": {
          "defaults": { "noValue": "沒有", "color": { "mode": "fixed", "fixedColor": "#808080" },
            "custom": { "align": "left", "cellOptions": { "type": "color-text", "wrapText": true } } },
          "overrides": []
        },
        "options": { "showHeader": false, "cellHeight": "sm" }
      },
      {
        "id": 24, "type": "stat", "title": "漏送通知",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 3, "w": 24, "x": 0, "y": 19 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "label_replace(label_join((max by (stuck_detail, data_time)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range])) * 0 + 1) * on() group_left(r) count_values(\"r\", sum(last_over_time(work_refund_unmatched{job=\"day25-work-view\"}[$__range]) and on(run) max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range]))) > 0), \"sub\", \"|\", \"stuck_detail\", \"r\", \"data_time\"), \"sub\", \"$1；其中 $2 筆是退款通知 · 資料時間 $3\", \"sub\", \"(.*)[|](.*)[|](.*)\") or label_replace(label_join((max by (stuck_detail, data_time)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range])) * 0 + 1) unless on() count_values(\"r\", sum(last_over_time(work_refund_unmatched{job=\"day25-work-view\"}[$__range]) and on(run) max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range]))) > 0), \"sub\", \"|\", \"stuck_detail\", \"data_time\"), \"sub\", \"$1 · 資料時間 $2\", \"sub\", \"(.*)[|](.*)\")" }
        ],
        "fieldConfig": { "defaults": { "noValue": "沒有漏送", "color": { "mode": "fixed", "fixedColor": "red" } }, "overrides": [] },
        "options": { "reduceOptions": { "values": false, "calcs": ["lastNotNull"], "fields": "/^sub$/" },
          "colorMode": "value", "graphMode": "none", "textMode": "value", "justifyMode": "center", "orientation": "auto", "wideLayout": true,
          "text": { "valueSize": 22, "titleSize": 16 } }
      },
      {
        "id": 25, "type": "stat", "title": "回得慢・資料未齊",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 3, "w": 24, "x": 0, "y": 22 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "label_replace(label_join(max by (scenario, status_text, stuck_detail, data_time)(last_over_time(work_status{job=\"day25-work-view\",status=\"unknown\"}[$__range])), \"sub\", \"|\", \"scenario\", \"status_text\", \"stuck_detail\", \"data_time\"), \"sub\", \"$1 · $2：$3 · 資料時間 $4\", \"sub\", \"(.*)[|](.*)[|](.*)[|](.*)\")" }
        ],
        "fieldConfig": { "defaults": { "noValue": "沒有", "color": { "mode": "fixed", "fixedColor": "#808080" } }, "overrides": [] },
        "options": { "reduceOptions": { "values": false, "calcs": ["lastNotNull"], "fields": "/^sub$/" },
          "colorMode": "value", "graphMode": "none", "textMode": "value", "justifyMode": "center", "orientation": "auto", "wideLayout": true,
          "text": { "valueSize": 22, "titleSize": 16 } }
      },
      { "id": 30, "type": "row", "title": "誰處理？", "collapsed": false, "gridPos": { "h": 1, "w": 24, "x": 0, "y": 25 }, "panels": [] },
      {
        "id": 31, "type": "table", "title": "",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 5, "w": 24, "x": 0, "y": 26 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "(max by (run, scenario, owner, next_step)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range]))*0+1) or (max by (run, scenario, owner, next_step)(last_over_time(work_status{job=\"day25-work-view\",status=\"unknown\"}[$__range]))*0+2)" }
        ],
        "transformations": [
          { "id": "sortBy", "options": { "fields": {}, "sort": [ { "field": "Value" } ] } },
          { "id": "organize", "options": {
            "excludeByName": { "Time": true, "run": true, "Value": true },
            "indexByName": { "scenario": 0, "owner": 1, "next_step": 2 },
            "renameByName": { "scenario": "項目", "owner": "誰處理", "next_step": "下一步" } } }
        ],
        "fieldConfig": {
          "defaults": { "noValue": "沒有", "custom": { "align": "left", "cellOptions": { "type": "auto", "wrapText": true } } },
          "overrides": []
        },
        "options": { "showHeader": true, "cellHeight": "sm" }
      },
      {
        "id": 40, "type": "row", "title": "哪幾筆？", "collapsed": true,
        "gridPos": { "h": 1, "w": 24, "x": 0, "y": 31 },
        "panels": [
          {
            "id": 41, "type": "table", "title": "",
            "datasource": { "type": "loki", "uid": "loki" },
            "gridPos": { "h": 10, "w": 24, "x": 0, "y": 32 },
