{
  "apiVersion": "dashboard.grafana.app/v1beta1",
  "kind": "Dashboard",
  "metadata": { "name": "day25-work-view-v7", "annotations": { "grafana.app/folder": "day25" } },
  "spec": {
    "uid": "day25-work-view-v7",
    "title": "取消的訂單都處理完了嗎？",
    "tags": ["day25", "notification"],
    "timezone": "browser",
    "schemaVersion": 36,
    "refresh": "",
    "time": { "from": "now-5m", "to": "now" },
    "templating": { "list": [] },
    "panels": [
      {
        "id": 50, "type": "stat", "title": "一句話結論",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 3, "w": 18, "x": 0, "y": 0 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "last_over_time(work_summary{job=\"day25-work-view\"}[$__range])" }
        ],
        "fieldConfig": { "defaults": { "noValue": "看不到", "color": { "mode": "fixed", "fixedColor": "text" } }, "overrides": [] },
        "options": { "reduceOptions": { "values": false, "calcs": ["lastNotNull"], "fields": "/^summary$/" },
          "colorMode": "none", "graphMode": "none", "textMode": "value", "justifyMode": "center", "orientation": "auto", "wideLayout": true,
          "text": { "titleSize": 16 } }
      },
      {
        "id": 51, "type": "stat", "title": "下一步",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 3, "w": 6, "x": 18, "y": 0 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "last_over_time(work_summary{job=\"day25-work-view\"}[$__range])" }
        ],
        "fieldConfig": { "defaults": { "noValue": "看不到", "color": { "mode": "fixed", "fixedColor": "text" } }, "overrides": [] },
        "options": { "reduceOptions": { "values": false, "calcs": ["lastNotNull"], "fields": "/^next$/" },
          "colorMode": "none", "graphMode": "none", "textMode": "value", "justifyMode": "center", "orientation": "auto", "wideLayout": true,
          "text": { "titleSize": 16 } }
      },
      {
        "id": 1, "type": "stat", "title": "狀態",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 5, "w": 6, "x": 0, "y": 3 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "min((max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range]))*0+1) or (max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"unknown\"}[$__range]))*0+2) or (max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"matched\"}[$__range]))*0+3))" }
        ],
        "fieldConfig": {
          "defaults": { "noValue": "看不到", "color": { "mode": "thresholds" },
            "mappings": [ { "type": "value", "options": {
              "1": { "text": "✗ 沒處理完", "color": "red", "index": 0 },
              "2": { "text": "? 紀錄不全", "color": "#808080", "index": 1 },
              "3": { "text": "✓ 都處理完了", "color": "green", "index": 2 } } } ] },
          "overrides": []
        },
        "options": { "reduceOptions": { "values": false, "calcs": ["lastNotNull"], "fields": "/^Value$/" },
          "colorMode": "background", "graphMode": "none", "textMode": "value", "justifyMode": "center", "orientation": "auto", "wideLayout": true,
          "text": { "titleSize": 18 } }
      },
      {
        "id": 2, "type": "stat", "title": "取消成功",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 5, "w": 6, "x": 6, "y": 3 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "(sum(abs(max by (run)(last_over_time(flow_count{job=\"day25-work-view\",stage_order=\"2\"}[$__range])) - on(run) max by (run)(last_over_time(request_outcome{job=\"day25-work-view\",outcome=\"取消成功\"}[$__range])))) + sum(last_over_time(request_outcome{job=\"day25-work-view\",outcome=\"系統錯誤\"}[$__range]))) or vector(0)" }
        ],
        "fieldConfig": {
          "defaults": { "color": { "mode": "thresholds" },
            "mappings": [
              { "type": "value", "options": { "0": { "text": "✓ 全部", "color": "green", "index": 0 } } },
              { "type": "range", "options": { "from": 0.0001, "to": 1000000000, "result": { "text": "✗ 有缺", "color": "red", "index": 1 } } } ] },
          "overrides": []
        },
        "options": { "reduceOptions": { "values": false, "calcs": ["lastNotNull"], "fields": "/^Value$/" },
          "colorMode": "background", "graphMode": "none", "textMode": "value", "justifyMode": "center", "orientation": "auto", "wideLayout": true,
          "text": { "titleSize": 18 } }
      },
      {
        "id": 3, "type": "stat", "title": "客人被告知",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 5, "w": 6, "x": 12, "y": 3 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "100 * sum(last_over_time(work_matched{job=\"day25-work-view\"}[$__range]) and on(run) (max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range])) or (max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"matched\"}[$__range])) unless on() max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range]))))) / sum(last_over_time(work_expected{job=\"day25-work-view\"}[$__range]) and on(run) (max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range])) or (max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"matched\"}[$__range])) unless on() max by (run)(last_over_time(work_status{job=\"day25-work-view\",status=\"investigate\"}[$__range]))))) " }
        ],
        "fieldConfig": {
          "defaults": { "unit": "percent", "decimals": 0, "noValue": "看不到", "color": { "mode": "thresholds" },
            "thresholds": { "mode": "absolute", "steps": [ { "color": "red", "value": null }, { "color": "green", "value": 100 } ] },
            "mappings": [] },
          "overrides": []
        },
        "options": { "reduceOptions": { "values": false, "calcs": ["lastNotNull"], "fields": "/^Value$/" },
          "colorMode": "background", "graphMode": "none", "textMode": "value", "justifyMode": "center", "orientation": "auto", "wideLayout": true,
          "text": { "titleSize": 18 } }
      },
      {
        "id": 4, "type": "stat", "title": "退款",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 5, "w": 6, "x": 18, "y": 3 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
            "expr": "(max(last_over_time(flow_stage_info{job=\"day25-work-view\",stage_order=\"7\",available=\"看不到\"}[$__range]))*0+3) or (max(last_over_time(flow_stage_info{job=\"day25-work-view\",stage_order=\"7\",available=\"有\"}[$__range]))*0+1)" }
        ],
        "fieldConfig": {
          "defaults": { "noValue": "看不到", "color": { "mode": "thresholds" },
            "mappings": [ { "type": "value", "options": {
              "3": { "text": "看不到", "color": "#808080", "index": 0 },
              "1": { "text": "有資料", "color": "green", "index": 1 } } } ] },
          "overrides": []
        },
        "options": { "reduceOptions": { "values": false, "calcs": ["lastNotNull"], "fields": "/^Value$/" },
          "colorMode": "background", "graphMode": "none", "textMode": "value", "justifyMode": "center", "orientation": "auto", "wideLayout": true,
          "text": { "titleSize": 18 } }
      },
      {
        "id": 11, "type": "stat", "title": "",
        "datasource": { "type": "prometheus", "uid": "prometheus" },
        "gridPos": { "h": 2, "w": 6, "x": 0, "y": 8 },
        "targets": [
          { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
